import java.util.ArrayList;


public class Caso {
	private String nombreCaso;
	private int codigoCaso;
	private String nombreDetective;
	private Ubicacion[] ubicaciones;
	private ArrayList<Pista> pistas;

	public Caso() {
		nombreCaso = "";
		codigoCaso = 0;
		nombreDetective = "";
		ubicaciones = new Ubicacion[5];
		pistas = new ArrayList<Pista>();
	}
	
	public Caso(String nombreCaso, int codigoCaso, String nombreDetective) {
		this.nombreCaso = nombreCaso;
		this.codigoCaso = codigoCaso;
		this.nombreDetective = nombreDetective;
		ubicaciones = new Ubicacion[5];
		pistas = new ArrayList<Pista>();
	}
	
	public void setNombreCaso(String newNombre) {
		nombreCaso = newNombre;
	}
	
	public String getNombreCaso() {
		return nombreCaso;
	}
	
	public void setCodigoCaso(int newCodigo) {
		codigoCaso = newCodigo;
	}
	
	public int getCodigoCaso() {
		return codigoCaso;
	}
	
	public void setNombreDetective(String newNombre) {
		nombreDetective = newNombre;
	}
	
	public String getNombreDetective() {
		return nombreDetective;
	}
	
	public void registrarUbicacion(int posicion, Ubicacion ubicacion) {
		int indice = posicion - 1;

		if (indice >= 0 && indice < ubicaciones.length){
			if (ubicaciones[indice] == null){
				ubicaciones[indice] = ubicacion;
			}
		}
	}
	
	public Ubicacion consultarUbicacion(int posicion) {

    	int indice = posicion - 1;
    	if (indice >= 0 && indice < ubicaciones.length) {
        	return ubicaciones[indice];
    	}

    	return null;
	}
	
	public void mostrarUbicaciones() {
    	for (int i = 0; i < ubicaciones.length; i++) {
				if (ubicaciones[i] != null) {

            	System.out.println("Posición: " + (i + 1));
            	System.out.println("Código: " + ubicaciones[i].getCodigoUbicacion());
            	System.out.println("Nombre: " + ubicaciones[i].getNombreUbicacion());
            	System.out.println("Descripción: " + ubicaciones[i].getDescripcionUbicacion());
            	System.out.println("Nivel de riesgo: " + ubicaciones[i].getNivelRiesgo());
            	System.out.println("Estado: " + ubicaciones[i].getEstado());
            	System.out.println();
        	}
    	}
	}
	
	public void modificarUbicacion(int posicion, int newRiesgo, String newEstado) {
		int indice = posicion - 1;
    	if (indice >= 0 && indice < ubicaciones.length) {
        	if (ubicaciones[indice] != null) {
            	ubicaciones[indice].setNivelRiesgo(newRiesgo);
            	ubicaciones[indice].setEstado(newEstado);
        	}
    	}
	}
	
	public void descartarUbicacion(int posicion) {
		int indice = posicion - 1;
		if (indice >= 0 && indice < ubicaciones.length){
			if (ubicaciones[indice] != null){
				ubicaciones[indice] = null;
			}
		}
	}
	
	public void registrarPista(Pista pista) {
    	if (buscarPista(pista.getCodigoPista()) == null) {
        	pistas.add(pista);
    	}
	}
	
	public void mostrarPistas() {
		for (Pista pista : pistas) {
        	System.out.println("Código: " + pista.getCodigoPista());
        	System.out.println("Descripción: " + pista.getDescripcionPista());
        	System.out.println("Evidencia: " + pista.getEvidencia());
        	System.out.println("Importancia: " + pista.getImportancia());
        	System.out.println("Confiabilidad: " + pista.getConfiabilidad());
        	System.out.println("\n");
    	}
	}
	
	public Pista buscarPista(int codigo) {
    	for (int i = 0; i < pistas.size(); i++) {
        	if (pistas.get(i).getCodigoPista() == codigo) {
            	return pistas.get(i);
        	}
    	}
    	return null;
	}
	
	public void modificarPista(int codigo, String newDescripcion, String newEvidencia, int newImportancia, int newConfiabilidad) {
		Pista pista = buscarPista(codigo);
    	if (pista != null) {
        	pista.setDescripcionPista(newDescripcion);
        	pista.setEvidencia(newEvidencia);
        	pista.setImportancia(newImportancia);
        	pista.setConfiabilidad(newConfiabilidad);
    	}
	}
	
	public void descartarPista(int codigo) {
    	Pista pista = buscarPista(codigo);
    	if (pista != null) {
        	pistas.remove(pista);
    	}
	}
	
	public int cantidadUbicaciones() {
		int cantidad = 0;
    	for (int i = 0; i < ubicaciones.length; i++) {
        	if (ubicaciones[i] != null) {
            	cantidad++;
        	}
    	}
    	return cantidad;
	}
	
	public int espaciosDisponibles() {
		return 5 - cantidadUbicaciones();
	}
	
	public int cantidadPistas() {
		return pistas.size();
	}
	
	public Ubicacion mayorRiesgo() {
		Ubicacion mayor = null;
    	for (int i = 0; i < ubicaciones.length; i++) {
        	if (ubicaciones[i] != null) {
            	if (mayor == null || ubicaciones[i].getNivelRiesgo() > mayor.getNivelRiesgo()) {
            		mayor = ubicaciones[i];
            	}
        	}
    	}
    	return mayor;
	}
	
	public Pista mayorImportancia() {
		Pista mayor = null;
		for (Pista pista : pistas) {
        	if (mayor == null || pista.getImportancia() > mayor.getImportancia()) {
				mayor = pista;
        	}
    	}
    	return mayor;
	}
	
	public Pista mayorConfiabilidad() {
		Pista mayor = null;
    	for (Pista pista : pistas) {
        	if (mayor == null || pista.getConfiabilidad() > mayor.getConfiabilidad()) {
            	mayor = pista;
        	}
    	}
    	return mayor;
	}
	
	public float promedioImportancia() {
		int suma = 0;
    	for (Pista pista : pistas) {
        	suma += pista.getImportancia();
    	}
    	if (pistas.size() == 0) {
        	return 0;
    	}
    return (float) suma / pistas.size();
	}
}
